import { describe, it, expect } from 'vitest'
import {
  num,
  pos,
  clamp01,
  pert,
  totalLoc,
  tokenCost,
  subscriptionCost,
  oversightCost,
  aiLocPerDay,
  aiTimeDays,
  humanLocPerDay,
  humanTimeDays,
  cocomoCalc,
  applyBuffer,
} from './calc.js'
import { makeInitialState } from './defaults.js'

describe('numeric guards', () => {
  it('num coerces strings and rejects non-finite', () => {
    expect(num('42')).toBe(42)
    expect(num(3.5)).toBe(3.5)
    expect(num('abc')).toBe(0)
    expect(num(undefined)).toBe(0)
    expect(num(NaN)).toBe(0)
    expect(num(Infinity)).toBe(0)
  })

  it('pos returns 0 for non-positive or bad input (divide-by-zero guard)', () => {
    expect(pos(5)).toBe(5)
    expect(pos(0)).toBe(0)
    expect(pos(-5)).toBe(0)
    expect(pos('nope')).toBe(0)
  })

  it('clamp01 clamps into [0, 1]', () => {
    expect(clamp01(0.5)).toBe(0.5)
    expect(clamp01(-1)).toBe(0)
    expect(clamp01(2)).toBe(1)
    expect(clamp01('bad')).toBe(0)
  })
})

describe('pert', () => {
  it('computes the three-point weighted average', () => {
    expect(pert(10, 20, 30)).toBeCloseTo(20)
    expect(pert(0, 100, 200)).toBeCloseTo(100)
  })

  it('is skewed toward the most-likely value', () => {
    // o=0, m=10, p=100 -> (0 + 40 + 100)/6 = 23.33, well below the midpoint of 50
    expect(pert(0, 10, 100)).toBeCloseTo(23.333, 2)
  })
})

describe('totalLoc', () => {
  const complexityMap = { Moderate: { o: 700, m: 1200, p: 2000 } }

  it('sums LOC across areas and derives PERT expected + sigma', () => {
    const areas = [
      { mode: 'complexity', complexity: 'Moderate' },
      { mode: 'manual', loc: { o: 100, m: 200, p: 300 } },
    ]
    const result = totalLoc(areas, complexityMap)
    expect(result.o).toBe(800)
    expect(result.m).toBe(1400)
    expect(result.p).toBe(2300)
    expect(result.e).toBeCloseTo(pert(800, 1400, 2300))
    expect(result.sigma).toBeCloseTo(Math.abs(2300 - 800) / 6)
  })

  it('never yields a negative sigma even when optimistic > pessimistic', () => {
    const areas = [{ mode: 'manual', loc: { o: 500, m: 300, p: 100 } }]
    const result = totalLoc(areas, complexityMap)
    expect(result.sigma).toBeGreaterThanOrEqual(0)
  })

  it('handles an empty area list without dividing by zero', () => {
    const result = totalLoc([], complexityMap)
    expect(result).toEqual({ o: 0, m: 0, p: 0, e: 0, sigma: 0 })
  })
})

describe('tokenCost caching/batch discount logic', () => {
  const model = { in: 3, out: 15 }
  const baseAi = {
    tokensPerLocInput: 30,
    tokensPerLocOutput: 10,
    reworkMultiplier: 1,
    cachingEnabled: false,
    cachedFraction: 0.5,
    cacheDiscount: 0.9,
    batchEnabled: false,
    batchDiscount: 0.5,
  }

  it('computes cost with no discounts applied', () => {
    const result = tokenCost(1000, baseAi, model)
    expect(result.inTok).toBe(30000)
    expect(result.outTok).toBe(10000)
    expect(result.inCost).toBeCloseTo((30000 / 1e6) * 3)
    expect(result.outCost).toBeCloseTo((10000 / 1e6) * 15)
    expect(result.total).toBeCloseTo(result.inCost + result.outCost)
  })

  it('applies caching discount only to input cost when enabled', () => {
    const noCache = tokenCost(1000, baseAi, model)
    const cached = tokenCost(1000, { ...baseAi, cachingEnabled: true }, model)
    expect(cached.outCost).toBeCloseTo(noCache.outCost) // output untouched
    expect(cached.inCost).toBeLessThan(noCache.inCost)
    // cacheMult = 1 - 0.5*0.9 = 0.55
    expect(cached.inCost).toBeCloseTo(noCache.inCost * 0.55)
  })

  it('applies batch discount to the combined total when enabled', () => {
    const noBatch = tokenCost(1000, baseAi, model)
    const batched = tokenCost(1000, { ...baseAi, batchEnabled: true }, model)
    expect(batched.total).toBeCloseTo(noBatch.total * 0.5)
  })

  it('stacks caching and batch discounts', () => {
    const both = tokenCost(1000, { ...baseAi, cachingEnabled: true, batchEnabled: true }, model)
    const expectedIn = (30000 / 1e6) * 3 * 0.55
    const expectedOut = (10000 / 1e6) * 15
    expect(both.total).toBeCloseTo((expectedIn + expectedOut) * 0.5)
  })

  it('guards against a missing model (divide-by-zero-ish bad input)', () => {
    const result = tokenCost(1000, baseAi, undefined)
    expect(result.inCost).toBe(0)
    expect(result.outCost).toBe(0)
    expect(result.total).toBe(0)
  })
})

describe('subscriptionCost', () => {
  it('returns 0 when there is no plan', () => {
    expect(subscriptionCost(3, {}, null)).toBe(0)
  })

  it('multiplies price by months for a flat (non-per-seat) plan', () => {
    expect(subscriptionCost(2, { seats: 5 }, { price: 20, perSeat: false })).toBeCloseTo(40)
  })

  it('multiplies price by seats and months for a per-seat plan', () => {
    expect(subscriptionCost(2, { seats: 5 }, { price: 20, perSeat: true })).toBeCloseTo(200)
  })

  it('never goes negative on negative months', () => {
    expect(subscriptionCost(-5, { seats: 1 }, { price: 20, perSeat: false })).toBe(0)
  })
})

describe('oversightCost', () => {
  const state = makeInitialState()

  it('scales with oversight people, time fraction, and months', () => {
    const cost = oversightCost(2, state)
    const loadedMonthly = state.human.salariesUS.Mid * state.human.fullyLoadedMultiplier / 12
    const expected = state.ai.oversightPeople * state.ai.oversightTimeFraction * loadedMonthly * 2
    expect(cost).toBeCloseTo(expected)
  })

  it('never goes negative for negative months', () => {
    expect(oversightCost(-3, state)).toBe(0)
  })

  it('clamps oversightTimeFraction into [0, 1]', () => {
    const overFraction = { ...state, ai: { ...state.ai, oversightTimeFraction: 5 } }
    const clamped = { ...state, ai: { ...state.ai, oversightTimeFraction: 1 } }
    expect(oversightCost(1, overFraction)).toBeCloseTo(oversightCost(1, clamped))
  })
})

describe('divide-by-zero guards on velocity/effort', () => {
  it('aiTimeDays returns NaN (not Infinity) when AI velocity is zero', () => {
    const state = makeInitialState()
    state.ai.productivityMultiplier = 0
    expect(aiLocPerDay(state)).toBe(0)
    expect(Number.isNaN(aiTimeDays(1000, state))).toBe(true)
  })

  it('humanTimeDays returns NaN (not Infinity) when the team is empty', () => {
    const state = makeInitialState()
    state.human.team = { Junior: 0, Mid: 0, Senior: 0, Staff: 0 }
    expect(humanLocPerDay(state)).toBe(0)
    expect(Number.isNaN(humanTimeDays(1000, state))).toBe(true)
  })
})

describe('cocomoCalc', () => {
  const state = makeInitialState()

  it('returns all zeros for zero or negative LOC', () => {
    expect(cocomoCalc(0, state)).toEqual({ effort: 0, months: 0, cost: 0, modeName: 'Organic' })
    expect(cocomoCalc(-100, state).effort).toBe(0)
  })

  it('computes effort/months/cost via the basic COCOMO formula for the selected mode', () => {
    const mode = state.human.cocomoModes.find((m) => m.id === state.human.cocomoModeId)
    const kloc = 10000 / 1000
    const expectedEffort = mode.a * Math.pow(kloc, mode.b)
    const expectedMonths = mode.c * Math.pow(expectedEffort, mode.d)
    const result = cocomoCalc(10000, state)
    expect(result.effort).toBeCloseTo(expectedEffort)
    expect(result.months).toBeCloseTo(expectedMonths)
    expect(result.modeName).toBe(mode.name)
    expect(result.cost).toBeGreaterThan(0)
  })
})

describe('applyBuffer', () => {
  it('applies a percentage increase when requested', () => {
    expect(applyBuffer(100, 25, true)).toBeCloseTo(125)
  })

  it('passes the value through unchanged when not applied', () => {
    expect(applyBuffer(100, 25, false)).toBe(100)
  })

  it('passes NaN through unchanged rather than propagating garbage math', () => {
    expect(Number.isNaN(applyBuffer(NaN, 25, true))).toBe(true)
  })
})

