    expect(subscriptionCost(2, { seats: 5 }, { price: 20, perSeat: true })).toBeCloseTo(200)
  })

  it('never goes negative on negative months', () => {
    expect(subscriptionCost(-5, { seats: 1 }, { price: 20, perSeat: false })).toBe(0)
  })
})

describe('oversightCost', () => {
  const state = makeInitialState()

  it('scales with oversight people, time fraction, and months', () => {
    const cost = oversightCost(2, state)
    const loadedMonthly = state.human.salariesUS.Mid * state.human.fullyLoadedMultiplier / 12
    const expected = state.ai.oversightPeople * state.ai.oversightTimeFraction * loadedMonthly * 2
    expect(cost).toBeCloseTo(expected)
  })

  it('never goes negative for negative months', () => {
    expect(oversightCost(-3, state)).toBe(0)
  })

  it('clamps oversightTimeFraction into [0, 1]', () => {
    const overFraction = { ...state, ai: { ...state.ai, oversightTimeFraction: 5 } }
    const clamped = { ...state, ai: { ...state.ai, oversightTimeFraction: 1 } }
    expect(oversightCost(1, overFraction)).toBeCloseTo(oversightCost(1, clamped))
  })
})

describe('divide-by-zero guards on velocity/effort', () => {
