})

describe('cocomoCalc', () => {
  const state = makeInitialState()

  it('returns all zeros for zero or negative LOC', () => {
    expect(cocomoCalc(0, state)).toEqual({ effort: 0, months: 0, cost: 0, modeName: 'Organic' })
    expect(cocomoCalc(-100, state).effort).toBe(0)
  })

  it('computes effort/months/cost via the basic COCOMO formula for the selected mode', () => {
    const mode = state.human.cocomoModes.find((m) => m.id === state.human.cocomoModeId)
    const kloc = 10000 / 1000
    const expectedEffort = mode.a * Math.pow(kloc, mode.b)
    const expectedMonths = mode.c * Math.pow(expectedEffort, mode.d)
    const result = cocomoCalc(10000, state)
    expect(result.effort).toBeCloseTo(expectedEffort)
    expect(result.months).toBeCloseTo(expectedMonths)
    expect(result.modeName).toBe(mode.name)
    expect(result.cost).toBeGreaterThan(0)
  })
})

describe('applyBuffer', () => {
  it('applies a percentage increase when requested', () => {
    expect(applyBuffer(100, 25, true)).toBeCloseTo(125)
  })

  it('passes the value through unchanged when not applied', () => {
    expect(applyBuffer(100, 25, false)).toBe(100)
  })

  it('passes NaN through unchanged rather than propagating garbage math', () => {
    expect(Number.isNaN(applyBuffer(NaN, 25, true))).toBe(true)
  })
})
